mapper.select:
SELECT id, habit_name, period, category_name, life_time, life_img, org_code FROM (SELECT dict.id, habit_name, period, category_name, life_time, life_img, org_code FROM yh_life_habit_dict dict INNER JOIN yh_life_habit_dict_category cate ON dict.habit_type = cate.id WHERE dict.remind_time IS NULL
and habit_type=#{habitType}
and habit_name like CONCAT('%',#{habitName},'%' )
ORDER BY life_time DESC ) a LIMIT #{page},#{limit}

SELECT count(1) FROM yh_life_habit_dict dict INNER JOIN yh_life_habit_dict_category cate ON dict.habit_type = cate.id WHERE dict.remind_time IS NULL
and habit_type=#{habitType}
and habit_name like CONCAT('%',#{habitName},'%' )
